import sys

data = sys.stdin.read().split()
n = int(data[0])
a = [int(x) for x in data[1:1 + n]]
best = None
for flip in [-1] + list(range(n)):
    b = a[:]
    if flip >= 0:
        b[flip] = -b[flip]
    for i in range(n):
        s = 0
        for j in range(i, n):
            s += b[j]
            if best is None or s > best:
                best = s
print(best)

