def gen(rng):
    def fmt(a):
        return "%d\n%s" % (len(a), " ".join(map(str, a)))
    M = 10**9
    tests = [fmt([5]), fmt([-5]), fmt([0]), fmt([0, 0, 0]), fmt([-1, -1, -1]), fmt([3, 4, 5]), fmt([2, -5, 3]),
             fmt([-4, -2, -7]), fmt([1, -2, 3, -4, 5]), fmt([-M, M, -M]), fmt([-M, -M, -M, -M])]
    for n in (2, 3, 4, 5, 6, 8, 10, 14):
        for _ in range(3):
            hi = rng.choice([3, 10, 50])
            tests.append(fmt([rng.randint(-hi, hi) for _ in range(n)]))
    N = 100000
    tests.append(fmt([rng.randint(-M, M) for _ in range(N)]))
    tests.append(fmt([-rng.randint(1, M) for _ in range(N)]))
    tests.append(fmt([rng.randint(0, M) for _ in range(N)]))
    tests.append(fmt([rng.choice([-1, 1]) * rng.randint(M - 5, M) for _ in range(N)]))
    return tests

